mapper.select:
select * from ( select m.id as id, 'COVER' as kind, m.url as url, m.width as width, m.height as height, p.id as post_id, p.happened_at as taken_at from post_media m join post p on p.id = m.post_id
p.visibility = 'PUBLIC' and p.status = 'PUBLISHED'
union all select a.id as id, 'ALBUM' as kind, a.url as url, a.width as width, a.height as height, null as post_id, a.created_at as taken_at from album_photo a ) photos order by photos.taken_at desc, photos.kind asc, photos.id desc limit #{limit} offset #{offset}

select ( select count(*) from post_media m join post p on p.id = m.post_id
p.visibility = 'PUBLIC' and p.status = 'PUBLISHED'
) + ( select count(*) from album_photo )

select id, user_id, url, width, height, created_at
from album_photo
where id = #{id}
